const body = $input.first().json.body || $input.first().json;

// Support GitHub Actions and GitLab CI webhook payloads
let parsed = {};

if (body.action && body.workflow_run) {
  // GitHub Actions
  const run = body.workflow_run;
  parsed = {
    source: 'GitHub Actions',
    repo: run.repository?.full_name || body.repository?.full_name || 'unknown',
    workflow: run.name || 'unknown',
    branch: run.head_branch || 'unknown',
    commit: run.head_sha?.substring(0, 7) || 'unknown',
    commitMessage: run.head_commit?.message || 'N/A',
    author: run.actor?.login || run.triggering_actor?.login || 'unknown',
    status: run.conclusion || run.status || 'unknown',
    url: run.html_url || '',
    runId: run.id || '',
    failedAt: run.updated_at || new Date().toISOString()
  };
} else if (body.object_kind === 'pipeline') {
  // GitLab CI
  parsed = {
    source: 'GitLab CI',
    repo: body.project?.path_with_namespace || 'unknown',
    workflow: body.object_attributes?.name || `Pipeline #${body.object_attributes?.id}`,
    branch: body.object_attributes?.ref || 'unknown',
    commit: body.commit?.id?.substring(0, 7) || 'unknown',
    commitMessage: body.commit?.message || 'N/A',
    author: body.user?.name || body.user?.username || 'unknown',
    status: body.object_attributes?.status || 'unknown',
    url: body.object_attributes?.url || body.project?.web_url || '',
    runId: body.object_attributes?.id || '',
    failedAt: body.object_attributes?.finished_at || new Date().toISOString()
  };
} else {
  parsed = {
    source: 'Unknown CI',
    repo: body.repo || body.repository || 'unknown',
    workflow: body.workflow || body.pipeline || 'unknown',
    branch: body.branch || body.ref || 'unknown',
    commit: body.commit || body.sha || 'unknown',
    commitMessage: body.message || 'N/A',
    author: body.author || body.user || 'unknown',
    status: body.status || body.conclusion || 'failed',
    url: body.url || '',
    runId: body.run_id || body.id || '',
    failedAt: new Date().toISOString()
  };
}

parsed.timestamp = new Date().toISOString();
return [{ json: parsed }];

